package com.clearing.shared.events;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * Event published to the {@code trade-submitted} Kafka topic when a new trade
 * is accepted by the TradeService and persisted to the database.
 *
 * <p>Partition key: {@code tradeId}
 * <p>Consumer: PositionService (for validation and position updates)
 *
 * <p>This record is the entry point of the Kafka clearing pipeline.
 */
public record TradeSubmittedEvent(

        /**
         * Unique identifier for the trade. Generated by TradeService as a UUID string.
         * This is the idempotency key — duplicate submissions with the same tradeId
         * must be detected and rejected at the DB constraint level.
         */
        String tradeId,

        /** Account ID of the buy-side participant. */
        String buyerAccountId,

        /** Account ID of the sell-side participant. */
        String sellerAccountId,

        /** Identifier of the financial instrument being traded (e.g. "AAPL"). */
        String instrumentId,

        /** Number of shares to transfer. Must be greater than 0. */
        Integer quantity,

        /** Price per share at the time of trade execution. */
        BigDecimal price,

        /** UTC timestamp when the trade was submitted to the platform. */
        Instant timestamp
) {
}
